#!/bin/bash
sed -i 's/const val EMPTY = "EMPTY"/const val EMPTY = "EMPTY"\n    const val SHORTCUT = "SHORTCUT"/g' /app/applet/app/src/main/java/com/example/data/Entities.kt

sed -i 's/ActionType.URL -> {/ActionType.SHORTCUT -> {\n                    val parts = target.split("||")\n                    if (parts.size == 2) {\n                        val packageName = parts[0]\n                        val shortcutId = parts[1]\n                        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.N_MR1) {\n                            val launcherApps = context.getSystemService(Context.LAUNCHER_APPS_SERVICE) as android.content.pm.LauncherApps\n                            try {\n                                launcherApps.startShortcut(packageName, shortcutId, null, null, android.os.Process.myUserHandle())\n                            } catch(e: Exception) { android.widget.Toast.makeText(context, "Shortcut failed", android.widget.Toast.LENGTH_SHORT).show() }\n                        }\n                    }\n                }\n                ActionType.URL -> {/g' /app/applet/app/src/main/java/com/example/features/ActionRouter.kt
